function ActivityNightCatDialog:InitHandler()
    SetButtonAction(self.BtnTower, Bind(self, self.BtnTowerOnClickHandler))
    SetButtonAction(self.BtnGachapon, Bind(self, self.BtnGachaponOnClickHandler))
    SetButtonAction(self.BtnPlay, Bind(self, self.BtnPlayOnClickHandler))
