    self._homeDataUpdateEvent = Events.AddListener(Constants.EventNames.ActivityNightCatHomeDataUpdate, Bind(self, self.HomeDataUpdateEventHandler))
    self._chapterDataUpdateEvent = Events.AddListener(Constants.EventNames.ActivityNightCatChapterDataUpdate, Bind(self, self.ChapterDataUpdateEventHandler))
end

function ActivityNightCatDialog:InitData()
    local argument = self.controller.Argument.parameters
    if argument.questId then
        -- 战斗返回
        self:SetActivityId(argument.activityId)
        self:SetQuestId(argument.questId)
        self:SetQuestType(QuestType.BATTLE)
        self:SetClearChapter(argument.clearChapter)
        self:SetUnlockChapters(argument.unlockChapters)
        ActivityNightCatMgr:UpdateHomeData(self:GetActivityId())
    else
        -- 活动进入
        self:SetActivityId(argument.activityId)
        ActivityNightCatMgr:UpdateHomeData(self:GetActivityId())
    end
    self._nightCatComponent:StartTimeDown()
end

function ActivityNightCatDialog:RefreshBossNode()
