    CfUtils.SetUISwitchImage(self.BtnBoss.transform:Find("Imgboss"), isUnlock and 1 or 2)
end

function ActivityNightCatDialog:BtnBossOnClickHandler()
    local switchImage = CfUtils.GetOrAddComponent(self.BtnBoss.transform:Find("Imgboss"), UISwitchImage)
    if switchImage.Status == 1 then
        UIModule.OpenDialog({
            id = Constants.UITypeIds.UINightCatBossDialog,
            parameters = {
                activityId = self:GetActivityId()
            }
        }, {
            { id = Constants.UITypeIds.ActivityNightCatDialog }
        })
    elseif switchImage.Status == 2 then
        GameUtils.Toast(localize("通关侵蚀空间50层后开启"))
    end
end

