---爬塔按钮点击回调
function ActivityNightCatDialog:BtnTowerOnClickHandler()
    if self:GetPlotPlaying() then return end
    
    self._isTowerEnter = true
    local rect = self.ScrollViewPanel.transform:Find("Viewport/Content").gameObject:GetComponent(typeof(CS.UnityEngine.RectTransform))
    local min = rect.offsetMin
    local max = rect.offsetMax
    CS.Engine.Lib.KCookie.Set("IsNightCatITowerEntry", "1")

    UIModule.OpenDialog({ id = Constants.UITypeIds.UINightCatITowerDialog, parameters = { offsetMax = max, offsetMin = min } })
    
    if self._aniCo ~= nil then
        cs_coroutine.stop(self._aniCo)
    end
    UIRaycastBlocker:AddCondition("ActivityNightCatEnterTowerAnimation")
    self._aniCo = cs_coroutine.start(function()
        -- 转场动画
        CfUtils.PlayAnimator(self.AnimRoot, "Transition")
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.5))
        UIRaycastBlocker:RemoveCondition("ActivityNightCatEnterTowerAnimation")
        UIModule.CloseDialog(self.controller)
    end)
end

