function ActivityNightCatDialog:BtnChapterOnClickHandler(chapterId, plotId)
    if self:GetPlotPlaying() then return end
    
    local chapterDojo = ActivityNightCatMgr:GetChapterDojoByChapterId(chapterId)
    if chapterDojo.state == ActivityNightCatConstants.ChapterState.LOCK then
        GameUtils.Toast(chapterDojo.tips)
    else
        UIModule.OpenDialog(
            { id = Constants.UITypeIds.ActivityNightCatPlotDialog, parameters = { chapterDojo = chapterDojo, plotId = plotId}}
        )
    end
end

