--region private
---检查序章
function ActivityNightCatDialog:CheckPrologue()
    local storyId = ActivityNightCatMgr:GetPrologueStoryId()
    local unlockPlot = ActivityNightCatMgr:GetUnlockPlotInfo()
    if checkInt(unlockPlot[tostring(storyId)]) == 2 then return end

    local questChapterVo = CfUtils.GetCfVo(AutoIds.IdSetting2733, "NightCatPlotVo", storyId)
    ActivityNightCatMgr:EnterQuest(questChapterVo.regionId)
    self:SetPlotPlaying(true)
end

---检查战斗返回
function ActivityNightCatDialog:CheckQuestBack()
    if self:GetQuestId() <= 0 then return end
    
    local plotId = ActivityNightCatMgr:GetPlotIdByQuestId(self:GetQuestId())
    local plotVo = CfUtils.GetCfVo(AutoIds.IdSetting2733, "NightCatPlotVo", plotId)
    -- 判断战斗结果
    if checkInt(plotVo.type) ~= Constants.QuestBattleType.Story then
        local questId = ActivityNightCatMgr:GetPlotInfoByChapterId(plotVo.chapter)
        if questId ~= self:GetQuestId() then
            self:SetClearChapter(0)
            self:SetUnlockChapters({})
        end
    end
    
    -- 判断章节完成
    if self:GetClearChapter() ~= 0 then return end
    
    -- 判断章节解锁
    if next(self:GetUnlockChapters()) ~= nil then return end
    
    -- 序章不处理
    local storyId = ActivityNightCatMgr:GetPrologueStoryId()
    if plotId == storyId then return end

    -- 回到前置关卡
    self:BtnChapterOnClickHandler(plotVo.chapter, plotId)
end

