---刷新列表位置
function ActivityNightCatDialog:RefreshScrollViewPos()
    local chapterData = ActivityNightCatMgr:GetChapterData()
    local offset = nil
    local pos = nil
    for id, v in pairs(chapterData) do
        if v.state == ActivityNightCatConstants.ChapterState.UNLOCK then
            if checkInt(v.pos) > checkInt(pos) then
                offset = v.offset
            end
        end
    end
    if offset then
        local tmp = string.split2(offset, ';')
        self.ScrollViewContent.anchoredPosition = Vector2.New(checkInt(tmp[1]), checkInt(tmp[2]))
    else
        self.ScrollViewContent.anchoredPosition = Vector2.New(0, 0)
    end
end

---刷新章节列表
function ActivityNightCatDialog:RefreshChapterGroup()
    local chapterData = ActivityNightCatMgr:GetChapterData()
    local aniNodes = {}
    if self:GetClearChapter() ~= 0 then
        if self._aniCo ~= nil then
            cs_coroutine.stop(self._aniCo)
        end
        self._aniCo = cs_coroutine.start(function()
            -- 初始化状态
            for _, chapterId in ipairs(self:GetUnlockChapters()) do
                local unlockNode = self.ChapterGroup:Find('ChapterNode_' .. chapterId)
                if not isNull(unlockNode) then
                    self:ChangeChapterNodeState(unlockNode, ActivityNightCatConstants.ChapterState.LOCK)
                    aniNodes[tostring(chapterId)] = true
                    SetButtonAction(unlockNode, function()
                        self:BtnChapterOnClickHandler(chapterId)
                    end)
                end
            end
            
            -- 完成动画
            local clearChapter = self:GetClearChapter()
            local node = self.ChapterGroup:Find('ChapterNode_' .. clearChapter)
            if not isNull(node) then
                SetButtonAction(node, function()
                    self:BtnChapterOnClickHandler(clearChapter)
                end)
                self:ChangeChapterNodeState(node, ActivityNightCatConstants.ChapterState.FINISH)
                local animRoot = node:Find("AnimRoot")
                local statusComplete = animRoot.transform:Find("StatusComplete")
                local animation = statusComplete.transform:GetComponent(typeof(CS.UnityEngine.Animation))
                if self:GetQuestType() == QuestType.BATTLE then
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
                end
                animation:Play('NightCatInstanceMainDialogChapterCompleteOpen')
                aniNodes[tostring(clearChapter)] = true
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(animation.clip.length + 0.16))
            end

            -- 解锁动画
            for _, chapterId in ipairs(self:GetUnlockChapters()) do
                local unlockNode = self.ChapterGroup:Find('ChapterNode_' .. chapterId)
                if not isNull(unlockNode) then
                    local animRoot = unlockNode:Find("AnimRoot")   
                    local animation = animRoot.transform:GetComponent(typeof(CS.UnityEngine.Animation))
                    animation:Play("NightCatInstanceChapterChange" .. chapterId)

                    cs_coroutine.start(function()
                        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
                        self:ChangeChapterNodeState(unlockNode, ActivityNightCatConstants.ChapterState.UNLOCK)
                        local statusUnderway = animRoot.transform:Find("StatusUnderway")
                        local animation2 = statusUnderway.transform:GetComponent(typeof(CS.UnityEngine.Animation))
                        if not KTool.IsNull(animation) then
                            animation2:PlayQueued('NightCatInstanceChapterUnderwayOpen', CS.UnityEngine.QueueMode.CompleteOthers)
                            animation2:PlayQueued('NightCatInstanceChapterUnderwayLoop', CS.UnityEngine.QueueMode.CompleteOthers)
                        end
                    end)
                end
            end
        end)
    end
    
    for id, v in pairs(chapterData) do
        if not aniNodes[tostring(id)] then
            local node = self.ChapterGroup:Find('ChapterNode_' .. id)
            if not isNull(node) then
                self:RefreshChapterNode(node, v)
            end
        end
    end
end

