---刷新章节node
---@param node UnityEngine.RectTransform 
---@param chapterDojo ActivityNightCatChapterDojo 
function ActivityNightCatDialog:RefreshChapterNode(node, chapterDojo)
    if isNull(node) then return end
    
    SetButtonAction(node, function() 
        self:BtnChapterOnClickHandler(chapterDojo.id)
    end)
    
    self:ChangeChapterNodeState(node, chapterDojo.state)
    
    -- 播放动画
    local animRoot = node:Find("AnimRoot")
    if chapterDojo.state == ActivityNightCatConstants.ChapterState.LOCK then
    elseif chapterDojo.state == ActivityNightCatConstants.ChapterState.UNLOCK then
        local statusUnderway = animRoot.transform:Find("StatusUnderway")
        local animation = statusUnderway.transform:GetComponent(typeof(CS.UnityEngine.Animation))
        if not KTool.IsNull(animation) then
            animation:PlayQueued('NightCatInstanceChapterUnderwayOpen', CS.UnityEngine.QueueMode.CompleteOthers)
            animation:PlayQueued('NightCatInstanceChapterUnderwayLoop', CS.UnityEngine.QueueMode.CompleteOthers)
        end
    elseif chapterDojo.state == ActivityNightCatConstants.ChapterState.FINISH then
    end
end

