---改变章节锁定状态
---@param node UnityEngine.RectTransform
---@param state integer
function ActivityNightCatDialog:ChangeChapterNodeState(node, state)
    if isNull(node) then return end
    
    local animRoot = node:Find("AnimRoot")
    local statusUnlock = animRoot.transform:Find("statusUnlock")
    local statusLock = animRoot.transform:Find("StatusLock")
    local statusComplete = animRoot.transform:Find("StatusComplete")
    local statusUnderway = animRoot.transform:Find("StatusUnderway")

    if checkInt(state) == ActivityNightCatConstants.ChapterState.LOCK then
        KTool.SetActive(statusLock, true)
        KTool.SetActive(statusUnlock, false)
        KTool.SetActive(statusComplete, false)
        KTool.SetActive(statusUnderway, false)
    elseif checkInt(state) == ActivityNightCatConstants.ChapterState.UNLOCK then
        KTool.SetActive(statusLock, false)
        KTool.SetActive(statusUnlock, true)
        KTool.SetActive(statusComplete, false)
        KTool.SetActive(statusUnderway, true)
    elseif checkInt(state) == ActivityNightCatConstants.ChapterState.FINISH then
        KTool.SetActive(statusLock, false)
        KTool.SetActive(statusUnlock, true)
        KTool.SetActive(statusComplete, true)
        KTool.SetActive(statusUnderway, false)
    end
end

